const SHAPES=[{id:'soft',name:'Soft',description:'Rounded, easygoing corners'},{id:'square',name:'Pixel',description:'Crisp edges and solid borders'},{id:'pill',name:'Bubble',description:'Extra-round controls and cards'}];
const APPEARANCE_DEFAULTS={palette:'green-dark',font:'system',shape:'soft'};
function normalizeAppearance(value={}){const legacy={lime:'green-dark',violet:'purple-dark',ocean:'blue-dark',ember:'orange-dark',rose:'pink-dark',daylight:'green-light'};value={...value,palette:legacy[value.palette]||value.palette};return {palette:PALETTES.some(p=>p.id===value.palette)?value.palette:'green-dark',font:FONTS.some(f=>f.id===value.font)?value.font:'system',shape:SHAPES.some(s=>s.id===value.shape)?value.shape:'soft'};}
function applyAppearance(value,root=document.documentElement){const appearance=normalizeAppearance(value),palette=PALETTES.find(p=>p.id===appearance.palette),font=FONTS.find(f=>f.id===appearance.font);for(const key of ['accent','bg','panel','text','muted','line','ink'])root.style.setProperty('--'+key,palette[key]);root.style.setProperty('--font',font.stack);root.dataset.palette=appearance.palette;root.dataset.font=appearance.font;root.dataset.shape=appearance.shape;root.style.colorScheme=appearance.palette.endsWith('-light')?'light':'dark';return appearance;}
function appearanceMarkup(prefs){const p=normalizeAppearance(prefs);return `<section class="panel appearance-panel"><div class="appearance-heading"><div><div class="eyebrow">MAKE IT YOURS</div><h2>Set the mood.</h2><p>A new color. A different feel. Still your RetroPal.</p></div><button class="btn small ghost" data-action="reset-appearance">Reset appearance</button></div><fieldset class="appearance-fieldset"><legend>Color palette</legend><div class="palette-options">${PALETTES.map(c=>`<label class="palette-choice" style="--preview-bg:${c.bg};--preview-panel:${c.panel};--preview-accent:${c.accent}"><input type="radio" name="palette" data-appearance="palette" value="${c.id}" ${p.palette===c.id?'checked':''}><span class="palette-scene" aria-hidden="true"><i></i><b></b><em></em></span><span class="choice-title">${c.name}<span class="choice-check" aria-hidden="true">✓</span></span><small>${c.description}</small></label>`).join('')}</div></fieldset><div class="appearance-lower"><fieldset class="appearance-fieldset"><legend>Typography</legend><div class="font-options">${FONTS.map(f=>`<label class="font-choice"><input type="radio" name="font" data-appearance="font" value="${f.id}" ${p.font===f.id?'checked':''}><span class="font-sample" style="font-family:${f.stack.replaceAll('"','&quot;')}">Aa</span><span><strong>${f.name}</strong><small>${f.sample}</small></span></label>`).join('')}</div><p class="appearance-hint">11 fonts included with RetroPal, plus four familiar device styles.</p></fieldset><fieldset class="appearance-fieldset"><legend>Interface shape</legend><div class="shape-options">${SHAPES.map(s=>`<label class="shape-choice"><input type="radio" name="shape" data-appearance="shape" value="${s.id}" ${p.shape===s.id?'checked':''}><span class="shape-example ${s.id}" aria-hidden="true"></span><span><strong>${s.name}</strong><small>${s.description}</small></span></label>`).join('')}</div></fieldset></div><div class="appearance-preview"><div><span class="eyebrow">LIVE PREVIEW</span><h3>Good games. Your style.</h3><p>Changes apply everywhere and save on this device.</p></div><div class="preview-components" aria-hidden="true"><span class="badge">PLAYER ONE</span><span class="preview-button">▶ Let's play</span></div></div><p id="appearance-status" class="appearance-hint" role="status" aria-live="polite">Your current look is saved.</p></section>`;}

// Dialog elements cannot enter fullscreen. Target their ordinary inner wrapper.
// A browser denial falls back to viewport expansion without interrupting play.
function createFullscreenController({doc,target,isOpen,setExpanded,onChange=()=>{},onFallback=()=>{}}){
  let expanded=false,busy=false,generation=0;
  const sync=()=>onChange(!!doc.fullscreenElement||expanded,expanded);
  async function toggle(){
    if(busy||!isOpen())return;
    const requestedGeneration=generation;
    busy=true;
    try{
      if(doc.fullscreenElement){await doc.exitFullscreen();expanded=false;setExpanded(false);}
      else if(expanded){expanded=false;setExpanded(false);}
      else{
        const element=target();
        try{if(!element||typeof element.requestFullscreen!=='function'||doc.fullscreenEnabled===false)throw new Error('Fullscreen is unavailable');await element.requestFullscreen();if(requestedGeneration!==generation||!isOpen()){if(doc.fullscreenElement)await doc.exitFullscreen();}}
        catch{if(requestedGeneration===generation&&isOpen()){expanded=true;setExpanded(true);onFallback();}}
      }
    }catch{onFallback();}finally{busy=false;sync();}
  }
  async function reset(){generation++;expanded=false;setExpanded(false);try{if(doc.fullscreenElement)await doc.exitFullscreen();}catch{}sync();}
  return {toggle,reset,sync,isExpanded:()=>expanded};
}

function applyBrand(value,doc=document){
  const {accent,ink}=PALETTES.find(p=>p.id===normalizeAppearance(value).palette);
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect x="1" y="1" width="62" height="62" rx="19" fill="${accent}"/><path d="M23 21h18c6 0 8 5 10 13l2 8c1 7-5 10-9 5l-6-6H26l-6 6c-4 5-10 2-9-5l2-8c2-8 4-13 10-13Z" fill="${ink}"/><path d="M23 27v12m-6-6h12" stroke="${accent}" stroke-width="4" stroke-linecap="round"/><circle cx="41" cy="29" r="2.8" fill="${accent}"/><circle cx="46" cy="36" r="2.8" fill="${accent}"/><path d="M27 18h10" stroke="${ink}" stroke-width="3" stroke-linecap="round"/></svg>`;
  const url='data:image/svg+xml,'+encodeURIComponent(svg);
  for(const logo of doc.querySelectorAll('.brand-logo'))if(logo.getAttribute('src')!==url)logo.setAttribute('src',url);
  const favicon=doc.querySelector('link[rel="icon"]');
  if(favicon&&favicon.getAttribute('href')!==url)favicon.setAttribute('href',url);
}

const $=s=>document.querySelector(s), heroHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">OLD FAVORITES. NEW SAVE FILES.</div><h2>Your next adventure.<br><span>One play away.</span></h2><p>A home for every cartridge, pocket-sized world, and late-night boss battle.</p><button class="btn primary" id="first-import">${icon('upload')} Import your first game</button></div><div class="hero-art" aria-hidden="true"><div class="art-tile"><small>POCKET CLASSICS</small><b>GB<br>A.</b><small>EST. 2001</small></div><div class="art-tile"><small>16-BIT GENERATION</small><b>SU<br>PER.</b><small>EST. 1990</small></div><div class="art-tile"><small>THE ORIGINAL</small><b>8-BIT<br>LOVE.</b><small>EST. 1983</small></div></div></section>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bytes=n=>n>=1024**3?(n/1024**3).toFixed(1)+' GB':n>=1024**2?(n/1024**2).toFixed(1)+' MB':Math.ceil(n/1024)+' KB';
// Library organization, visit statistics, session history, and bounded manual saves.
let folders=[],sessions=[],libraryScope='all',folderId='',focusedGameId='',historyPage=0;
let visitInfo={streak:1,lastDay:''},dailyPick=null,legacySeconds=0;
let savesRequest=0,manualQueue=Promise.resolve(),sessionQueue=Promise.resolve(),sessionTicker;
let overlayWasPaused=true,overlayFocus=null;
const tabIdentity=(()=>{try{let id=sessionStorage.getItem('retropal-tab');if(!id){id=crypto.randomUUID();sessionStorage.setItem('retropal-tab',id);}return id;}catch{return crypto.randomUUID();}})();
function localDay(date=new Date()){return [date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-');}
function dayIndex(day){const [y,m,d]=day.split('-').map(Number);return Date.UTC(y,m-1,d)/86400000;}
function nextVisit(previous,today){if(previous?.lastDay===today)return previous;return {lastDay:today,streak:previous?.lastDay&&dayIndex(today)-dayIndex(previous.lastDay)===1?(previous.streak||1)+1:1};}
function duration(seconds){const n=Math.max(0,Math.floor(seconds||0));return n>=3600?`${Math.floor(n/3600)}h ${Math.floor(n%3600/60)}m`:n>=60?`${Math.floor(n/60)}m ${n%60}s`:`${n}s`;}
function stamp(time){return time?new Date(time).toLocaleString(): '—';}
function elapsed(session=activeGame){return session?Math.max(0,Math.floor((Date.now()-session.openedAt)/1000)):0;}
function replaceSession(record){sessions=sessions.filter(s=>s.id!==record.id);sessions.push(record);}
async function initializeDashboard(){
  [folders,sessions]=await Promise.all([db.all('folders'),db.all('sessions')]);
  const now=Date.now();
  for(const record of sessions.filter(s=>s.status==='open'&&(s.owner===tabIdentity||now-s.lastSeen>120000))){record.status='interrupted';record.closedAt=null;await db.put('sessions',record.id,record);}
  let baseline=await db.get('prefs','history-baseline');
  if(!baseline){baseline={seconds:games.reduce((sum,g)=>sum+(g.playSeconds||0),0)};await db.put('prefs','history-baseline',baseline);}
  legacySeconds=baseline.seconds||0;
  await updateVisit();
}
async function updateVisit(){
  visitInfo=await db.update('prefs','visits',old=>nextVisit(old,localDay()));
  const old=await db.get('prefs','daily-game');
  if(old?.day===localDay()&&gameById(old.id))dailyPick=old;
  else if(games.length){const id=games[Math.floor(Math.random()*games.length)].id;dailyPick={day:localDay(),id};await db.put('prefs','daily-game',dailyPick);}
  else dailyPick=null;
}
function homePage(){
  const daily=gameById(dailyPick?.id),most=games.map(g=>({...g,playSeconds:(g.playSeconds||0)+sessions.filter(s=>s.gameId===g.id&&s.status!=='closed').reduce((n,s)=>n+(s.seconds||0),0)})).filter(g=>g.playSeconds>0).sort((a,b)=>b.playSeconds-a.playSeconds)[0];
  const record=[...sessions].sort((a,b)=>(b.seconds||0)-(a.seconds||0))[0],total=legacySeconds+sessions.reduce((n,s)=>n+(s.seconds||0),0);
  const links=[['library','grid','Library','All your games and favorites in one place.'],['history','clock','History','Revisit your sessions and see how long you played.'],['personalize','palette','Personalize','Choose your colors, fonts, and interface style.'],['systems','cpu','All systems','Explore compatibility and supported file formats.'],['guide','book','Field guide','Controls, save files, and help getting started.'],['settings','settings','Settings','Device checks, automatic saves, and local storage.']];
  return `${head('Good to see you.','Your games. Your space. Your next adventure.',false)}<div class="home-hero"><section class="panel daily-panel"><div class="eyebrow">YOUR GAME OF THE DAY</div><h2>${daily?esc(daily.title):'A new favorite starts here.'}</h2><p>${daily?`${esc(byId(daily.system).name)} · A daily pick from your own library.`:'Add a game to your library to get a different daily pick.'}</p><div class="button-pair">${daily?action('play',daily.hasFile&&byId(daily.system).core?'Play today’s pick':'View compatibility','play',`data-id="${daily.id}"`,'btn primary')+action('go-game','View in library','arrow',`data-id="${daily.id}"`,'btn ghost'):'<a class="btn primary" href="#library">Build your library '+icon('arrow')+'</a>'}</div></section><section class="panel streak-panel"><span class="stat-icon">${icon('spark')}</span><strong class="stat-value">${visitInfo.streak}</strong><h2>Day${visitInfo.streak===1?'':'s'} in a row</h2></section></div><div class="stats-grid"><section class="panel"><div class="eyebrow">TOTAL TIME</div><strong class="stat-value">${(total/3600).toFixed(2)} <small>hours</small></strong><p>${duration(total)} across all tracked sessions</p></section><section class="panel"><div class="eyebrow">LONGEST SESSION</div><strong class="stat-value">${record?duration(record.seconds):'—'}</strong><p>${record?esc(record.title):'Play a game to set your first record.'}</p><small class="muted">Session records start with this update.</small></section><section class="panel"><div class="eyebrow">MOST PLAYED</div><h2>${most?esc(most.title):'Your next favorite'}</h2><p>${most?duration(most.playSeconds)+' played':'Your most-played library game will appear here.'}</p>${most?action('go-game','View game','arrow',`data-id="${most.id}"`,'text-link'):''}</section></div><div class="section-heading"><h2>Make yourself at home</h2></div><div class="home-links">${links.map(([page,ic,title,desc])=>`<a class="panel page-link" href="#${page}"><span class="stat-icon">${icon(ic)}</span><h3>${title}</h3><p>${desc}</p><span class="page-link-arrow">${icon('arrow')}</span></a>`).join('')}</div>`;
}
function libraryFolders(){return `<div class="library-tabs"><button class="chip ${libraryScope==='all'?'active':''}" data-action="library-scope" data-scope="all" aria-pressed="${libraryScope==='all'}">All games</button><button class="chip ${libraryScope==='favorites'?'active':''}" data-action="library-scope" data-scope="favorites" aria-pressed="${libraryScope==='favorites'}">${icon('heart')} Favorites</button></div>`;}
function folderNameDialog(id=''){const folder=folders.find(f=>f.id===id);showModal(folder?'Rename folder':'Create a favorite folder',`<label class="field">Folder name<input id="folder-name" maxlength="60" value="${esc(folder?.name||'')}" placeholder="Weekend favorites" autocomplete="off"></label>`,action('save-folder',folder?'Save name':'Create folder','check',`data-id="${id}"`,'btn primary'));$('#folder-name').focus();}
async function saveFolder(id){const name=$('#folder-name').value.trim();if(!name)return toast('Give your folder a name.');const old=folders.find(f=>f.id===id),folder={id:old?.id||crypto.randomUUID(),name,games:old?.games||[]};await db.put('folders',folder.id,folder);folders=folders.filter(f=>f.id!==folder.id).concat(folder);$('#modal').close();folderId=folder.id;libraryScope='favorites';focusedGameId='';query='';render();}
function folderPicker(id){const f=folders.find(f=>f.id===id);if(!f)return;const favorites=games.filter(g=>g.favorite);showModal(`Games in ${f.name}`,`<p>Choose from games you’ve already favorited.</p><div class="folder-picker">${favorites.map(g=>`<label class="picker-row"><input type="checkbox" data-folder-game="${g.id}" ${f.games.includes(g.id)?'checked':''}><span><strong>${esc(g.title)}</strong><small>${esc(byId(g.system).name)}</small></span></label>`).join('')||'<p class="empty-copy">No favorites yet. Close this panel and use the heart on a game in your library, then return here.</p>'}</div>`,action('save-folder-games','Save selection','check',`data-id="${id}"`,'btn primary'));}
async function saveFolderGames(id){const f=folders.find(f=>f.id===id);if(!f)return;const next={...f,games:[...document.querySelectorAll('[data-folder-game]:checked')].map(e=>e.dataset.folderGame).filter(id=>gameById(id)?.favorite)};await db.put('folders',id,next);folders=folders.map(f=>f.id===id?next:f);$('#modal').close();render();}
function historyPageMarkup(){const list=[...sessions].sort((a,b)=>b.openedAt-a.openedAt),size=30,pages=Math.max(1,Math.ceil(list.length/size));historyPage=Math.min(historyPage,pages-1);return `${head('Your play history.','Every session has a story. Pick a game to find it in your library.',false)}<section class="panel"><div class="section-heading"><h2>${list.length} session${list.length===1?'':'s'}</h2><small class="muted">Times shown in your device’s timezone</small></div>${list.length?`<div class="table-wrap"><table class="history-table"><thead><tr><th>Game</th><th>Opened</th><th>Closed</th><th>Session length</th></tr></thead><tbody>${list.slice(historyPage*size,(historyPage+1)*size).map(s=>`<tr><td>${gameById(s.gameId)?action('go-game',esc(s.title),'arrow',`data-id="${s.gameId}"`,'text-link history-game'):esc(s.title)+'<small>Removed from library</small>'}</td><td>${stamp(s.openedAt)}</td><td>${s.closedAt?stamp(s.closedAt):`<span>${s.status==='open'?'In progress':'Interrupted'}</span><small>Last seen ${stamp(s.lastSeen)}</small>`}</td><td>${duration(s.seconds)}</td></tr>`).join('')}</tbody></table></div><div class="pagination"><button class="btn small" data-action="history-prev" ${historyPage===0?'disabled':''}>Previous</button><span>Page ${historyPage+1} of ${pages}</span><button class="btn small" data-action="history-next" ${historyPage===pages-1?'disabled':''}>Next</button></div>`:'<div class="empty-copy"><h3>Your next session starts here.</h3><p>Open a game and your session will appear here. Older versions recorded totals, but not individual open and close times.</p><a class="btn" href="#library">Open library</a></div>'}</section>`;}
function goToGame(id){if(!gameById(id))return toast('This game is no longer in the library.');folderId='';libraryScope='all';family='all';systemFilter='';query='';focusedGameId=id;location.hash='library';render();$('#games')?.scrollIntoView({block:'center',behavior:prefs.reduceMotion?'instant':'smooth'});}
async function startSession(session){session.openedAt=Date.now();session.sessionId=crypto.randomUUID();session.historyRecord={id:session.sessionId,owner:tabIdentity,gameId:session.game.id,title:session.game.title,openedAt:session.openedAt,lastSeen:session.openedAt,closedAt:null,seconds:0,status:'open'};await db.put('sessions',session.sessionId,session.historyRecord);replaceSession(session.historyRecord);clearInterval(sessionTicker);sessionTicker=setInterval(()=>void checkpointSession(),15000);}
function checkpointSession(session=activeGame){if(!session?.historyRecord||session.ending)return Promise.resolve();const record={...session.historyRecord,lastSeen:Date.now(),seconds:elapsed(session)};session.historyRecord=record;replaceSession(record);sessionQueue=sessionQueue.catch(()=>{}).then(()=>db.put('sessions',record.id,record));return sessionQueue.catch(()=>toast('Session history could not be updated.'));}
async function finishSession(session){if(!session?.historyRecord||session.ending)return;session.ending=true;clearInterval(sessionTicker);const closedAt=Date.now(),seconds=elapsed(session);await sessionQueue.catch(()=>{});const record={...session.historyRecord,closedAt,lastSeen:closedAt,seconds,status:'closed'},g=gameById(session.game.id);const operations=[{store:'sessions',key:record.id,value:record}];if(g){const next={...g,playSeconds:(g.playSeconds||0)+record.seconds};operations.push({store:'games',key:g.id,value:next});await db.write(operations);Object.assign(g,next);}else await db.write(operations);replaceSession(record);}
function saveRecord(session,state){return {id:crypto.randomUUID(),state:new Blob([state]),core:byId(session.game.system).core,version:'4.2.3',size:session.file.size,savedAt:Date.now(),sessionId:session.sessionId,sessionSeconds:elapsed(session)};}
function saveManualState(session=activeGame,provided){if(!session?.started)return Promise.reject(new Error('Wait for the game to start before saving.'));let state=provided||$('#player iframe')?.contentWindow.retroPalSnapshot?.();if(!ArrayBuffer.isView(state)||!state.byteLength)return Promise.reject(new Error('This game does not support save states.'));const record=saveRecord(session,state);autoSaveStatus('Saving snapshot…',session);const operation=manualQueue.catch(()=>{}).then(()=>db.addManualState(session.game.id,record));manualQueue=operation;return operation.then(()=>{autoSaveStatus('Snapshot saved · '+stamp(record.savedAt),session);toast('Snapshot saved. Latest 10 kept for this game.');return record;},error=>{autoSaveStatus('Save failed. Previous snapshots are unchanged.',session);throw error;});}
function saveHistoryMarkup(id,records){const g=gameById(id);return `<p>Latest 10 manual snapshots for <strong>${esc(g?.title||'this game')}</strong>. A new snapshot replaces the oldest when full. Automatic resume is separate.</p><div class="save-list">${records.length?records.map((r,i)=>`<button class="save-row" data-action="restore-state" data-id="${id}" data-save="${r.id}"><span class="save-number">${String(i+1).padStart(2,'0')}</span><span><strong>${stamp(r.savedAt)}</strong><small>Session time: ${duration(r.sessionSeconds)} · ${bytes(r.state.size)}</small></span><span class="save-restore">Restore ${icon('arrow')}</span></button>`).join(''):'<div class="empty-copy"><h3>No manual snapshots yet.</h3><p>Use the save icon while playing. Existing automatic progress will still resume normally.</p></div>'}</div><div class="save-foot">${action('reset-state','Reset current state','restart',`data-id="${id}"`,'btn small ghost')}<small>Manual history and in-game saves are kept.</small></div>`;}
function playerOverlay(title,body){const shell=$('#player .player-shell');if(!shell)return;let overlay=$('#save-overlay');if(!overlay){overlayFocus=document.activeElement;overlayWasPaused=$('#player iframe')?.contentWindow.retroPalPause?.()??true;shell.querySelector('.modal-head').inert=true;shell.querySelector('.player-body').inert=true;overlay=document.createElement('div');overlay.id='save-overlay';overlay.className='save-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-labelledby','save-overlay-title');shell.append(overlay);}overlay.innerHTML=`<section class="save-sheet"><div class="modal-head"><h2 id="save-overlay-title">${esc(title)}</h2><button class="icon-btn" data-action="close-saves" aria-label="Close save history">${icon('close')}</button></div><div class="modal-body">${body}</div></section>`;overlay.querySelector('button')?.focus();}
function closeSaveOverlay(){const overlay=$('#save-overlay');if(!overlay)return;overlay.remove();const shell=$('#player .player-shell');if(shell){shell.querySelector('.modal-head').inert=false;shell.querySelector('.player-body').inert=false;}if(!overlayWasPaused)$('#player iframe')?.contentWindow.retroPalResume?.();if(overlayFocus?.isConnected)overlayFocus.focus();else $('[data-action="player-saves"]')?.focus();}
async function showSaveHistory(id){const request=++savesRequest;const records=(await db.get('saves',id))||[];if(request!==savesRequest)return;if(activeGame?.game.id===id&&$('#player').open)playerOverlay('Save history',saveHistoryMarkup(id,records));else showModal('Save history',saveHistoryMarkup(id,records),action('detail','Back to game','arrow',`data-id="${id}"`,'btn'));}
async function restoreState(id,saveId){await manualQueue.catch(()=>{});const records=await db.get('saves',id)||[],record=records.find(r=>r.id===saveId),g=gameById(id);if(!record||!g)throw new Error('This snapshot is no longer available.');if(record.core!==byId(g.system).core||record.size!==g.size||record.version!=='4.2.3')throw new Error('This snapshot does not match the current game or emulator.');if(activeGame?.game.id===id){await activeGame.saving;await $('#player iframe').contentWindow.retroPalRestoreState(record.state);await db.put('prefs','auto-state:'+id,record);closeSaveOverlay();autoSaveStatus('Restored snapshot · '+stamp(record.savedAt));toast('Snapshot restored.');}else{$('#modal').close();await play(id,{resume:record.state});}}
function confirmResetState(id){const body=`<p>Restart from the game’s boot screen and clear its automatic resume point?</p><p>Your 10 manual snapshots and in-game saves will be kept. This does not erase a game’s own save files.</p><div class="button-pair">${action('confirm-reset-state','Reset current state','restart',`data-id="${id}"`,'btn danger')}${action('game-saves','Cancel','close',`data-id="${id}"`,'btn')}</div>`;if(activeGame?.game.id===id)playerOverlay('Reset current state?',body);else showModal('Reset current state?',body);}
async function resetState(id){await manualQueue.catch(()=>{});if(activeGame?.game.id===id){await activeGame.saving;$('#player iframe').contentWindow.retroPalRestart();await db.remove('prefs','auto-state:'+id);closeSaveOverlay();autoSaveStatus('Game restarted · new progress will auto-save');}else{await db.remove('prefs','auto-state:'+id);$('#modal').close();}toast('Automatic state reset. Manual snapshots kept.');}
document.addEventListener('keydown',e=>{if(!$('#save-overlay'))return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeSaveOverlay();}if(e.key==='Tab'){const list=[...$('#save-overlay').querySelectorAll('button:not(:disabled),a,input')];const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}},true);
document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
  const handled=['new-folder','rename-folder','save-folder','open-folder','folder-games','save-folder-games','delete-folder','confirm-delete-folder','library-scope','go-game','history-prev','history-next','game-saves','player-saves','close-saves','restore-state','reset-state','confirm-reset-state'];if(!handled.includes(a))return;
  e.preventDefault();e.stopImmediatePropagation();
  try{
    if(a==='new-folder')folderNameDialog();else if(a==='rename-folder')folderNameDialog(id);else if(a==='save-folder')await saveFolder(id);
    else if(a==='open-folder'){folderId=id;libraryScope='favorites';focusedGameId='';query='';family='all';systemFilter='';render();}
    else if(a==='folder-games')folderPicker(id);else if(a==='save-folder-games')await saveFolderGames(id);
    else if(a==='delete-folder')showModal('Delete folder?',`<p>Delete ${esc(folders.find(f=>f.id===id)?.name||'this folder')}? Your games and favorites will stay in your library.</p>`,action('confirm-delete-folder','Delete folder','close',`data-id="${id}"`,'btn danger')+action('close','Keep folder','check','','btn'));
    else if(a==='confirm-delete-folder'){await db.remove('folders',id);folders=folders.filter(f=>f.id!==id);folderId='';$('#modal').close();render();}
    else if(a==='library-scope'){libraryScope=b.dataset.scope;folderId='';focusedGameId='';query='';render();}
    else if(a==='go-game')goToGame(id);
    else if(a==='history-prev'||a==='history-next'){historyPage+=a==='history-next'?1:-1;render();}
    else if(a==='game-saves'||a==='player-saves')await showSaveHistory(id||activeGame?.game.id);
    else if(a==='close-saves')closeSaveOverlay();else if(a==='restore-state')await restoreState(id,b.dataset.save);
    else if(a==='reset-state')confirmResetState(id);else if(a==='confirm-reset-state')await resetState(id);
  }catch(error){toast(error.message||'That change could not be saved.');}
},true);
window.addEventListener('message',e=>{if(e.source!==$('#player iframe')?.contentWindow||e.origin!==location.origin||e.data?.source!=='retropal-player')return;if(e.data.type==='manual-save'||e.data.type==='manual-save-request')void saveManualState(activeGame,e.data.detail?.state).catch(err=>toast(err.message));if(e.data.type==='open-saves')void showSaveHistory(activeGame?.game.id).catch(err=>toast(err.message));});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')void checkpointSession();else if(storageReady&&visitInfo.lastDay!==localDay())void updateVisit().then(()=>{if(route==='home')render();}).catch(()=>{});});
window.addEventListener('pagehide',event=>{if(event.persisted)void checkpointSession();else void finishSession(activeGame).catch(()=>{});});

const labels={home:'Home',library:'Library',history:'History',systems:'All systems',personalize:'Personalize',guide:'Field guide',settings:'Settings'};
let games=[],prefs={lowPower:true,reduceMotion:false,scanlines:false,volume:.7,autoSave:true,autoResume:true,...APPEARANCE_DEFAULTS},route='home',query='',family='all',systemFilter='',sort='added',view='grid',pending=[],importBusy=false,biosTarget='',detailId='',storageReady=false,toastTimer,activeGame=null,playStart=0,diagResults=null;
const fullScreen=createFullscreenController({doc:document,target:()=>$('#player .player-shell'),isOpen:()=>$('#player').open,setExpanded:value=>$('#player').classList.toggle('expanded',value),onChange:(active,expanded)=>{document.body.classList.toggle('player-fullscreen',active);$('#player iframe')?.contentWindow.postMessage({type:'fullscreen-state',active},location.origin);const button=$('[data-action="fullscreen"]');if(button){button.setAttribute('aria-label',active?'Exit fullscreen player':'Fullscreen player');button.setAttribute('aria-pressed',String(active));button.title=active?'Return to window':'Fullscreen';}if(!active&&$('#play-status')?.textContent.startsWith('Expanded view'))$('#play-status').textContent='Playing · use the emulator toolbar for controls and saves';},onFallback:()=>{if($('#play-status'))$('#play-status').textContent='Expanded view · this browser does not allow native fullscreen';}});
document.addEventListener('fullscreenchange',()=>fullScreen.sync());
document.addEventListener('retropal:toggle-fullscreen',()=>{void fullScreen.toggle();});
$('#player').addEventListener('cancel',event=>{if(fullScreen.isExpanded()||document.fullscreenElement){event.preventDefault();void fullScreen.toggle();}else{event.preventDefault();void closePlayer();}});
const gameById=id=>games.find(g=>g.id===id);
const tierLabel=s=>s.tier==='catalog'?'Catalog only':s.tier==='demanding'?'Device dependent':'Browser core';
const badge=s=>`<span class="badge ${s.tier==='catalog'?'native':''}">${tierLabel(s)}</span>`;
const options=(value,all=false)=>`${all?'<option value="">All systems</option>':''}${SYSTEMS.map(s=>`<option value="${s.id}" ${s.id===value?'selected':''}>${s.name}${s.tier==='catalog'?' · catalog only':''}</option>`).join('')}`;
const action=(name,label,ic='plus',extra='',cls='btn')=>`<button class="${cls}" data-action="${name}" ${extra}>${icon(ic)} ${label}</button>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function showModal(title,body,foot=''){const m=$('#modal');if(m.open)m.close();m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;m.showModal();}
function message(title,text){showModal(title,`<p>${esc(text)}</p>`,action('close','Got it','check','','btn primary'));}
function head(title,subtitle,button=true){return `<div class="page-head"><div><div class="eyebrow">${route==='library'?'PRESS PLAY ON A LITTLE NOSTALGIA':'YOUR COLLECTION. EVERY ERA.'}</div><h1>${title}</h1><p>${subtitle}</p></div>${button?action('import','Add games','plus','','btn primary'):''}</div>`;}
function applyPrefs(){Object.assign(prefs,applyAppearance(prefs));applyBrand(prefs);document.body.classList.toggle('reduce-motion',prefs.reduceMotion);document.body.classList.toggle('low-power',prefs.lowPower);$('#player').classList.toggle('scanlines',prefs.scanlines&&!prefs.lowPower);}
async function savePrefs(){applyPrefs();await db.put('prefs','settings',prefs);}
function render(){let hash=location.hash.slice(1)||'home';if(hash==='favorites'){hash='library';libraryScope='favorites';history.replaceState(null,'','#library');}if(hash==='recent'){hash='history';history.replaceState(null,'','#history');}route=labels[hash]?hash:'home';if(route==='home'&&games.length&&!gameById(dailyPick?.id))void updateVisit().then(()=>{if(route==='home')render();}).catch(()=>{});$('#library-count').textContent=games.length;document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===route);if(a.dataset.page===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const pages={home:homePage,library:libraryPage,history:historyPageMarkup,personalize:()=>head('Make it feel like you.','Your colors, your type, your way to play.',false)+appearanceMarkup(prefs),systems:systemsPage,guide:guidePage,settings:settingsPage};$('#main').innerHTML=`<section class="route-in">${pages[route]()}</section>`;if(route==='library')renderGames();if(route==='settings')refreshStorage();applyBrand(prefs);}
function libraryPage(){return `${head('Library','All your games and favorites. Together.')}${libraryFolders()}<div class="section-heading"><h2>${route==='library'?'Your collection':labels[route]} <span class="muted" id="result-count"></span></h2><div class="filters" aria-label="Filter by manufacturer">${['all','Nintendo','Sega','Sony','Atari'].map(f=>`<button class="chip ${family===f?'active':''}" data-action="family" data-family="${f}" aria-pressed="${family===f}">${f==='all'?'All games':f}</button>`).join('')}</div></div><div class="toolbar"><label class="search">${icon('search')}<input id="search" type="search" placeholder="Find your next game…" aria-label="Search your library" value="${esc(query)}"><kbd>/</kbd></label><div class="toolbar-right"><select id="system-filter" aria-label="Filter by system">${options(systemFilter,true)}</select><select id="sort" aria-label="Sort games"><option value="added" ${sort==='added'?'selected':''}>Recently added</option><option value="title" ${sort==='title'?'selected':''}>Title A–Z</option><option value="played" ${sort==='played'?'selected':''}>Last played</option></select><button class="icon-btn" data-action="view" aria-label="${view==='grid'?'Switch to list view':'Switch to grid view'}">${icon(view==='grid'?'list':'grid')}</button></div></div><div id="games"></div>`;}
function filteredGames(){const folder=folders.find(f=>f.id===folderId);let list=games.filter(g=>(!focusedGameId||g.id===focusedGameId)&&(libraryScope!=='favorites'||g.favorite)&&(!folder||g.favorite&&folder.games.includes(g.id))&&(family==='all'||byId(g.system)?.family===family)&&(!systemFilter||g.system===systemFilter)&&(`${g.title} ${g.filename} ${byId(g.system)?.name}`.toLowerCase().includes(query.toLowerCase())));list.sort((a,b)=>sort==='title'?a.title.localeCompare(b.title):sort==='played'?(b.lastPlayed||0)-(a.lastPlayed||0):b.added-a.added);return list;}
function renderGames(){$('#library-count').textContent=String(games.length);const list=filteredGames();$('#result-count').textContent=`/ ${list.length}`;const node=$('#games');if(!list.length&&(folderId||libraryScope==='favorites')){node.innerHTML=`<div class="no-results"><h3>${folderId?'Make room for your favorites.':'Your favorites belong here.'}</h3><p>${folderId?'Choose from games you have already favorited, or adjust your filters.':'Use a game’s heart button in All games to favorite it.'}</p>${folderId?action('folder-games','Choose games','plus',`data-id="${folderId}"`,'btn primary'):action('library-scope','Browse all games','grid','data-scope="all"','btn')}</div>`;return;}if(!list.length){node.innerHTML=games.length||route!=='library'?`<div class="no-results"><h3>${query||systemFilter||family!=='all'?'No games match these filters.':route==='favorites'?'Your favorites will live here.':route==='recent'?'Your next session starts here.':'No games found.'}</h3><p>${route==='favorites'?'Tap a heart on any game to save it here.':route==='recent'?'Launch a game from your library to start your history.':'Try another search or clear your filters.'}</p>${action('clear-filters','Show full library','grid','','btn ghost small')}</div>`:`<div class="empty-state"><div class="empty-icon">${icon('gamepad')}</div><div><h3>Great memories start with one game.</h3><p>Drop your ROMs here, or add games to start your collection.</p></div>${action('import','Add games','plus','','btn ghost')}</div>`;return;}node.innerHTML=`<div class="game-grid ${view==='list'?'list-view':''}">${list.map(g=>{const s=byId(g.system);return `<article class="game-card ${focusedGameId===g.id?'highlight-game':''}"><div class="cover" style="--sys:${s.color}">${g.cover?`<img src="${esc(g.cover)}" alt="" loading="lazy">`:`<span class="cover-brand">RETROPAL / ${s.short}</span><strong class="cover-title">${esc(g.title)}</strong><span class="cover-system">${s.family.toUpperCase()} · ${s.year}</span>`}<button class="cover-play" data-action="play" data-id="${g.id}" aria-label="${s.core?'Play':'View'} ${esc(g.title)}">${icon(s.core?'play':'book')}</button><button class="favorite ${g.favorite?'on':''}" data-action="favorite" data-id="${g.id}" aria-label="${g.favorite?'Unfavorite':'Favorite'} ${esc(g.title)}" aria-pressed="${!!g.favorite}">${icon('heart')}</button></div><div class="game-info"><div><h3>${esc(g.title)}</h3><p>${s.short} <span class="tiny-dot">·</span> ${s.tier==='catalog'?'Catalog only':g.hasFile?'Ready to launch':'Reimport to play'}</p></div><button class="icon-btn" data-action="detail" data-id="${g.id}" aria-label="Edit ${esc(g.title)}">${icon('more')}</button></div></article>`;}).join('')}</div>`;}
function systemsPage(){return `${head('All systems','19 systems to organize. 14 with browser cores.',false)}<div class="callout">Built for ChromeOS. Start with 8-bit, 16-bit, and handheld games. N64, DS, and PS1 performance depends on your device. Five newer systems are catalog-only.</div><div class="system-grid">${SYSTEMS.map(s=>`<article class="system-card" style="--sys:${s.color}"><div class="system-banner"><b>${s.short}</b><small>${s.year}</small></div><div class="system-body"><h3>${s.name}</h3><p>${s.ext.map(x=>'.'+x).join(' / ')}</p><div class="system-actions">${badge(s)}${action('system','Details','arrow',`data-id="${s.id}"`,'text-link')}</div></div></article>`).join('')}</div>`;}
function systemDetail(id){const s=byId(id);if(!s)return;showModal(s.name,`${badge(s)}<p style="margin-top:18px">${esc(s.note)}</p><p><strong>Formats:</strong> ${s.ext.map(x=>'.'+x).join(', ')}${s.core?', plus ZIP / 7z / RAR archives containing a game for this system.':'.'}</p><p>${s.tier==='light'?'A good place to start on a low-powered device. Actual game compatibility still varies.':s.tier==='demanding'?'Try a small game first. Close extra tabs and leave Low-power mode on.':''}</p><p>${games.filter(g=>g.system===id).length} games in your collection.</p>`,action('filter-system','View games','grid',`data-id="${id}"`)+action('import-system','Add games','plus',`data-id="${id}"`,'btn primary'));}
function toggle(key,title,description){return `<label class="settings-row"><div><h3>${title}</h3><p>${description}</p></div><input class="switch" type="checkbox" data-pref="${key}" ${prefs[key]?'checked':''} aria-label="${title}"></label>`;}
function settingsPage(){return `${head('Make yourself at home','A few small tweaks. A better play session.',false)}<div class="panel"><h2>Your device</h2><p>Check this browser before starting a longer adventure.</p><div class="settings-row"><div><h3>Device check</h3><p>Tests browser features, storage, and access to the bundled NES core.</p></div>${action('diagnostics','Run check','cpu','','btn small')}</div><div class="settings-row"><div><h3>Playable test cartridge</h3><p>An original NES input test. No game download needed.</p></div>${action('demo','Try it','play','','btn small')}</div><div id="diagnostics">${diagResults?diagnosticMarkup(diagResults):''}</div></div><div class="panel"><h2>Play your way</h2><p>Low-power mode is on by default for school devices.</p>${toggle('autoSave','Automatic save states','Save every 30 seconds, when hiding the tab, and when closing the player. Supported cores only. Saves stay in this browser.')} ${toggle('autoResume','Resume automatically','Load the latest automatic state when opening a game. Turn off to start from the game’s boot screen.')}<p class="appearance-hint">Keep using in-game saves and exported backups. A crash or forced shutdown can lose progress since the last completed save. Manual emulator save slots are separate.</p>${toggle('lowPower','Low-power mode','Stops ambient animation, disables scanlines, and limits imports to 128 MB per file.')}${toggle('reduceMotion','Reduced motion','Removes interface animations and transitions.')}${toggle('scanlines','CRT scanlines','A light overlay in the player. Disabled while Low-power mode is on.')}<div class="settings-row"><div><h3>Starting volume</h3><p>Applies the next time you launch a game.</p></div><label class="volume-control"><input type="range" id="volume" min="0" max="1" step="0.05" value="${prefs.volume}" aria-label="Starting volume"><output>${Math.round(prefs.volume*100)}%</output></label></div></div><div class="panel"><h2>BIOS & firmware</h2><p>Add files from your own hardware when a core needs them. Files stay in this browser. For a multi-file BIOS set, use a ZIP with the filenames expected by the core.</p>${['nes','a52','psx','gba','nds'].map(id=>`<div class="settings-row"><div><h3>${byId(id).name}</h3><p id="bios-status-${id}">Checking local BIOS…</p></div><div class="button-pair">${action('bios','Choose file','upload',`data-id="${id}"`,'btn small')}${action('remove-bios','Remove','close',`data-id="${id}"`,'btn small')}</div></div>`).join('')}</div><div class="panel"><h2>Your local data</h2><p id="storage-estimate">Checking storage…</p><div class="settings-row"><div><h3>Keep local data</h3><p>Ask Chrome for persistent storage. Managed devices can decline.</p></div>${action('persist','Request','shield','','btn small')}</div><div class="settings-row"><div><h3>Library metadata</h3><p>Export titles, systems, favorites, notes, and covers. ROMs, BIOS, and emulator saves are separate.</p></div>${action('export','Export JSON','download','','btn small')}</div><div class="settings-row"><div><h3>Restore metadata</h3><p>Restore an exported library. Reimport game files where needed.</p></div>${action('restore','Import JSON','upload','','btn small')}</div></div><div class="panel"><h2>About RetroPal</h2><p>Version 0.5 · device edition. Powered by EmulatorJS 4.2.3 and its upstream emulator cores. No account, analytics, game uploads, or included commercial games.</p><a class="text-link" href="THIRD_PARTY_NOTICES.md" target="_blank" rel="noopener">Credits, licenses & core sources ${icon('arrow')}</a></div>`;}
function guidePage(){const sections=[['01 / START HERE','Build your collection','<ol><li>Choose <strong>Add games</strong>, or drop files onto the library.</li><li>Confirm the system. BIN, ISO, ROM, CHD, and archives need a manual choice.</li><li>Choose <strong>Import</strong>. Playable files stay in this browser. Unsupported systems keep metadata only.</li><li>Click a cover to launch. Use its three-dot menu to edit details.</li></ol>'],['02 / TAKE CONTROL','Keyboard, controller, or touch','<p>Click inside the game before playing. Open the player settings to inspect or remap controls. The NES test cartridge uses arrow keys to move.</p><ul><li>The emulator toolbar provides pause, restart, volume, fullscreen, controls, and save tools.</li><li>Connect a USB/Bluetooth controller and press a button for Chrome to detect it.</li><li>Touch controls depend on the core and device.</li><li>Press <strong>/</strong> in the library to search. Escape closes dialogs; fullscreen may consume the first Escape.</li></ul>'],['03 / SAVE YOUR PROGRESS','Keep the good stuff','<p>Use the emulator toolbar to save/load states and export/import in-game saves. RetroPal tracks recent play and session time after a core starts.</p><p>Clearing browser data or a school profile reset can erase local games and saves. Export important saves to Files before signing out or resetting. Library JSON does not contain emulator saves or ROMs.</p>'],['04 / KNOW THE LIMITS','device compatibility','<p>GitHub Pages compatibility does not guarantee every game runs. Device speed, memory, Chrome settings, and school policy matter. RetroPal cannot override restrictions.</p><p>N64, DS, and PS1 are device dependent. PS2, GameCube, Wii, PSP, and Switch are catalog-only. The PSP core needs threading unavailable on standard GitHub Pages.</p>'],['05 / FILES & ARCHIVES','The right file for the right system','<ul><li>ZIP, 7z, and RAR are unpacked in memory by the emulator. Use one game per archive. Password-protected and some archive variants may fail.</li><li>For PS1 multi-track discs, ZIP the CUE and all referenced BIN files together, preserving filenames and relative folders.</li><li>CHD playback depends on the PS1 core and disc image. RVZ is catalog-only.</li><li>Low-power mode allows 128 MB per file; Standard mode allows 512 MB. Expanded archives must fit in memory too.</li><li>Use games and firmware you are entitled to use. No download service is included.</li></ul>'],['06 / QUICK FIXES',"When a game won't start",'<ol><li>Run <strong>Settings → Device check</strong> and try the test cartridge.</li><li>Check the system, file integrity, and required BIOS.</li><li>Close other tabs and try a smaller uncompressed cartridge.</li><li>Reload and try again. Keep scanlines off on slower devices.</li><li>If a school restriction blocks it, ask your school administrator. RetroPal has no bypass mechanism.</li></ol>']];return `${head('A little guidance. A lot of play.','Everything you need for your first session.',false)}<div class="guide-grid">${sections.map(([k,t,b])=>`<section class="panel"><div class="eyebrow">${k}</div><h3>${t}</h3>${b}</section>`).join('')}</div><section class="panel" style="margin-top:24px"><h2>Compatibility at a glance</h2><div class="table-wrap"><table class="compat-table"><thead><tr><th>System</th><th>File extensions</th><th>This build</th></tr></thead><tbody>${SYSTEMS.map(s=>`<tr><td>${s.name}</td><td>${s.ext.map(e=>'.'+e).join(', ')}</td><td>${badge(s)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function startImport(system=''){if(!storageReady)return toast('Local storage must be available to import games.');pending=[];showModal('Make room for a classic.',`<div class="drop-zone">${icon('upload')}<strong>Drop your games here</strong><small>Cartridges, disc images, ZIP, 7z, and RAR.</small>${action('choose-files','Choose files','plus','','btn primary')}</div><label class="field">System for these files<select id="import-system">${options(system,true).replace('All systems','Auto-detect when possible')}</select></label><p>Shared formats and archives need a system choice. Large or unsupported games are cataloged without storing their files.</p><div id="import-list"></div><div id="import-feedback" role="status"></div>`,action('close','Cancel','close')+action('commit-import','Import games','check','','btn primary'));}
function stageFiles(files){if(importBusy||!$('#import-list'))return;const selected=$('#import-system')?.value||'';for(const file of files){if(!accepted.includes(extension(file.name))){toast(`Skipped unsupported file: ${file.name}`);continue;}if(pending.length>=100){toast('Import up to 100 files at a time.');break;}const match=candidates(file.name);pending.push({file,system:selected||(match.length===1?match[0].id:'')});}renderPending();}
function renderPending(){const n=$('#import-list');if(n)n.innerHTML=pending.map((p,i)=>`<div class="import-row"><div><strong>${esc(p.file.name)}</strong><small>${bytes(p.file.size)}${p.system&&byId(p.system).tier==='catalog'?' · metadata only':''}</small></div><select data-import-index="${i}" aria-label="System for ${esc(p.file.name)}"><option value="">Choose a system…</option>${options(p.system)}</select><button class="icon-btn" data-action="unstage" data-index="${i}" aria-label="Remove ${esc(p.file.name)}">${icon('close')}</button></div>`).join('');}
async function commitImport(){if(importBusy)return;if(!pending.length)return toast('Choose at least one game.');if(pending.some(p=>!p.system))return toast('Choose a system for every file.');importBusy=true;const button=$('[data-action="commit-import"]');button.disabled=true;let added=0,duplicate=0,failed=0;const feedback=$('#import-feedback');feedback.replaceChildren();const note=(text,error=false)=>{const p=document.createElement('p');p.textContent=text;if(error)p.className='error';feedback.append(p);};try{for(const {file,system} of pending){const s=byId(system),ext=extension(file.name);if(!s.ext.includes(ext)&&!ARCHIVES.includes(ext)){note(`${file.name}: extension does not match ${s.name}.`,true);failed++;continue;}const hasFile=!!s.core&&file.size<=(prefs.lowPower?128:512)*1024**2;const fingerprint=`${file.name}|${file.size}|${file.lastModified}|${system}`;let record=games.find(g=>g.fingerprint===fingerprint);if(record?.hasFile){duplicate++;continue;}record={...(record||{id:crypto.randomUUID(),title:file.name.replace(/\.[^.]+$/,'').replace(/_/g,' '),added:Date.now(),favorite:false,notes:'',playSeconds:0}),filename:file.name,size:file.size,lastModified:file.lastModified,system,fingerprint,hasFile};try{await db.write([{store:'games',key:record.id,value:record},...(hasFile?[{store:'files',key:record.id,value:file}]:[])]);const i=games.findIndex(g=>g.id===record.id);if(i<0)games.push(record);else games[i]=record;$('#library-count').textContent=String(games.length);added++;if(s.core&&!hasFile)note(`${file.name}: cataloged only; exceeds the ${prefs.lowPower?128:512} MB import limit.`);}catch{failed++;note(`${file.name}: could not save. Storage may be full or restricted.`,true);}}render();if(!failed&&!feedback.children.length)$('#modal').close();else{pending=[];renderPending();}toast(`${added} imported · ${duplicate} already in library${failed?` · ${failed} need attention`:''}`);}finally{importBusy=false;button.disabled=false;}}
async function detail(id){const g=gameById(id);if(!g)return;detailId=id;const s=byId(g.system);showModal(g.title,`${badge(s)}<p style="margin-top:15px">${esc(g.filename)} · ${bytes(g.size)}<br>${g.lastPlayed?`Last played ${new Date(g.lastPlayed).toLocaleDateString()} · ${Math.floor((g.playSeconds||0)/60)} minutes tracked`:'Not played yet'}${!g.hasFile?'<br>Catalog entry — reimport the game file to play if supported.':''}</p><label class="field">Title<input id="detail-title" maxlength="150" value="${esc(g.title)}"></label><label class="field">System<select id="detail-system">${options(g.system)}</select></label><label class="field">Notes<textarea id="detail-notes" maxlength="3000" placeholder="Your next quest, a favorite memory…">${esc(g.notes||'')}</textarea></label><div class="detail-actions">${action('cover','Choose cover','upload','','btn small')}${g.cover?action('remove-cover','Remove cover','close','','btn small'):''}${action('game-saves','Save history','clock',`data-id="${g.id}"`,'btn small')}${action('reset-state','Reset current state','restart',`data-id="${g.id}"`,'btn small')}${action('remove-game','Remove game','close',`data-id="${g.id}"`,'btn small danger')}</div><p style="margin-top:20px">${esc(s.note)}</p>`,action('play',s.core?'Play':'Compatibility','play',`data-id="${g.id}"`)+action('save-detail','Save changes','check','','btn primary'));}
async function saveDetail(){const g=gameById(detailId),title=$('#detail-title').value.trim(),system=$('#detail-system').value;if(!title)return toast('Enter a title.');if(!byId(system).ext.includes(extension(g.filename))&&!ARCHIVES.includes(extension(g.filename)))return toast('That system does not match this extension.');const next={...g,title,system,notes:$('#detail-notes').value,fingerprint:`${g.filename}|${g.size}|${g.lastModified||0}|${system}`};await db.put('games',g.id,next);Object.assign(g,next);$('#modal').close();render();toast('Game updated.');}
async function favorite(id){const g=gameById(id);if(!g)return;const next={...g,favorite:!g.favorite};const changed=next.favorite?[]:folders.filter(f=>f.games.includes(id)).map(f=>({...f,games:f.games.filter(x=>x!==id)}));await db.write([{store:'games',key:id,value:next},...changed.map(f=>({store:'folders',key:f.id,value:f}))]);Object.assign(g,next);folders=folders.map(f=>changed.find(c=>c.id===f.id)||f);render();}
function removeGame(id){const g=gameById(id);showModal('Remove from your library?',`<p>${esc(g.title)} and its local game file, manual snapshots, and automatic resume point will be removed. Your original file and the emulator's in-game save storage are not deleted.</p>`,action('close','Keep game','close')+action('confirm-remove','Remove game','close',`data-id="${id}"`,'btn danger'));}
async function demo(){if(!storageReady)return toast('Local storage is unavailable.');let g=gameById('retropal-input-lab');if(!g?.hasFile){const r=await fetch('./demo/input-lab.nes');if(!r.ok)throw new Error('Test cartridge is missing.');const file=new File([await r.blob()],'input-lab.nes',{type:'application/octet-stream',lastModified:0});g={id:'retropal-input-lab',title:'RetroPal Input Lab',filename:file.name,size:file.size,system:'nes',added:Date.now(),favorite:false,notes:'Original test cartridge. Move the square with arrow keys. Real NES emulation.',hasFile:true,lastModified:0,playSeconds:0};await db.write([{store:'games',key:g.id,value:g},{store:'files',key:g.id,value:file}]);games=games.filter(x=>x.id!==g.id);games.push(g);}render();await play(g.id);}

let autoTimer;
let endingSession=Promise.resolve();
function autoSaveStatus(text,session=activeGame){if(session===activeGame&&$('#auto-save-status'))$('#auto-save-status').textContent=text;}
function saveAutomaticState(session=activeGame){
  if(!session||!prefs.autoSave||!session.started)return Promise.resolve(false);
  if(session.saving)return session.saving;
  let state;
  try{state=$('#player iframe')?.contentWindow.retroPalSnapshot?.();if(!state||!ArrayBuffer.isView(state)||!state.byteLength)throw new Error('This core does not support automatic states.');}
  catch(error){autoSaveStatus(error.message||'Automatic state unavailable. Use in-game saves.',session);return Promise.resolve(false);}
  const record={state:new Blob([state]),core:byId(session.game.system).core,version:'4.2.3',size:session.file.size,savedAt:Date.now()};
  autoSaveStatus('Saving progress…',session);
  session.saving=db.put('prefs','auto-state:'+session.game.id,record).then(()=>{autoSaveStatus('Progress saved · '+new Date(record.savedAt).toLocaleTimeString(),session);return true;},()=>{autoSaveStatus('Auto-save failed: storage may be full. Export a manual save.',session);toast('Progress could not be saved. Export a manual save before leaving.');return false;}).finally(()=>{session.saving=null;});
  return session.saving;
}
async function closePlayer(){const session=activeGame;if(session?.closing)return;if(session)session.closing=true;await saveAutomaticState(session);if(activeGame===session)$('#player').close();}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')void saveAutomaticState();});
window.addEventListener('pagehide',()=>{void saveAutomaticState();});

async function play(id,launch={}){await endingSession;const g=gameById(id);if(!g)return;const issue=launchIssue(g);if(issue)return message('Before you play',issue);const file=await db.get('files',id);if(!file)return message('Reimport this game','This is a catalog entry or its local file is missing. Add the original file to restore playback. Large files may exceed the device import limit.');const s=byId(g.system),bios=await db.get('bios',g.system);let resume=launch.resume||null;if(!resume&&!launch.fresh&&prefs.autoResume){try{const saved=await db.get('prefs','auto-state:'+id);if(saved?.state instanceof Blob&&saved.core===s.core&&saved.version==='4.2.3'&&saved.size===file.size)resume=saved.state;}catch{toast('Could not read the automatic save. Starting normally.');}}if((extension(g.filename)==='fds'||g.system==='a52')&&!bios)return message('A BIOS is needed',`${s.name} needs a BIOS for this file. Add it in Settings → BIOS & firmware.`);$('#modal').close();const p=$('#player');p.innerHTML=`<div class="player-shell"><div class="modal-head player-header"><div class="player-heading"><div class="player-brand-line"><span class="player-brand"><img class="brand-logo" src="favicon.svg" alt="">RetroPal</span><span class="player-divider" aria-hidden="true"></span><h2 id="player-title">${esc(g.title)}</h2></div></div><div class="button-pair"><button class="icon-btn" data-action="save-auto" aria-label="Save snapshot" title="Save snapshot">${icon('download')}</button><button class="icon-btn" data-action="player-saves" aria-label="Save history" title="Save history">${icon('clock')}</button><button class="icon-btn" data-action="fullscreen" aria-label="Fullscreen player">${icon('expand')}</button><button class="icon-btn" data-action="close-player" aria-label="Close player">${icon('close')}</button></div></div><div class="player-body"><iframe src="player.html" title="${esc(g.title)} emulator" allow="autoplay; fullscreen; gamepad" allowfullscreen></iframe></div></div>`;activeGame={game:g,file,bios:bios?.file,resume,started:false};playStart=0;try{await startSession(activeGame);}catch{toast('Session history could not be started.');}p.showModal();applyBrand(prefs);fullScreen.sync();}
async function endSession(){const current=activeGame;closeSaveOverlay();const finalSave=saveAutomaticState(current);clearInterval(autoTimer);activeGame=null;await fullScreen.reset();$('#player').innerHTML='';await finalSave;await manualQueue.catch(()=>{});await finishSession(current);playStart=0;await updateVisit();render();}
window.addEventListener('message',async e=>{const frame=$('#player iframe');if(!frame||e.source!==frame.contentWindow||e.origin!==location.origin||e.data?.source!=='retropal-player'||!activeGame)return;const type=e.data.type;if(type==='frame-ready')frame.contentWindow.postMessage({type:'load-game',game:activeGame.file,resume:activeGame.resume,bios:activeGame.bios,core:byId(activeGame.game.system).core,id:activeGame.game.id,volume:prefs.volume,accent:getComputedStyle(document.documentElement).getPropertyValue('--accent').trim()},location.origin);else if(type==='started'&&!playStart){fullScreen.sync();activeGame.started=true;autoSaveStatus(e.data.detail?.resumeMessage|| (prefs.autoSave?'Automatic save every 30 seconds':'Automatic saves off'));clearInterval(autoTimer);autoTimer=setInterval(()=>void saveAutomaticState(),30000);playStart=Date.now();activeGame.game.lastPlayed=playStart;try{await db.put('games',activeGame.game.id,activeGame.game);}catch{toast('Could not store play history.');}if($('#play-status'))$('#play-status').textContent='Playing · use the emulator toolbar for controls and saves';}else if(type==='error')toast('Could not start · check file, BIOS, and Device check');else if(type==='exit')$('#player').close();});
$('#player').addEventListener('close',()=>{endingSession=endSession().catch(()=>toast('Session time could not be saved.'));});
$('#modal').addEventListener('cancel',e=>{if(importBusy)e.preventDefault();});
async function refreshStorage(){try{const estimate=await navigator.storage?.estimate();if($('#storage-estimate'))$('#storage-estimate').textContent=estimate?`${bytes(estimate.usage||0)} used of approximately ${bytes(estimate.quota||0)} available for this site. Chrome manages this allowance.`:'Storage estimates are unavailable.';for(const id of ['nes','a52','psx','gba','nds']){const value=await db.get('bios',id);const n=$(`#bios-status-${id}`);if(n)n.textContent=value?value.name:'No BIOS file added';}}catch{if($('#storage-estimate'))$('#storage-estimate').textContent='Storage is unavailable or restricted.';}}
function diagnosticMarkup(results){return `<div class="diagnostic-list">${results.map(r=>`<div><span class="${r.ok?'success':'error'}">${icon(r.ok?'check':'close')}</span><span><strong>${esc(r.name)}</strong><small>${esc(r.detail)}</small></span></div>`).join('')}<p>These checks verify prerequisites, not game speed or universal compatibility. Try the NES cartridge next.</p></div>`;}
async function diagnostics(){const results=[],add=(name,ok,detail)=>results.push({name,ok,detail});add('WebAssembly',typeof WebAssembly==='object',typeof WebAssembly==='object'?'Available for emulator cores.':'Unavailable or restricted.');const canvas=document.createElement('canvas'),gl=canvas.getContext('webgl2')||canvas.getContext('webgl');add('Graphics',!!gl,gl?'WebGL is available.':'WebGL unavailable; games may fail.');gl?.getExtension('WEBGL_lose_context')?.loseContext();try{await db.put('prefs','diagnostic',Date.now());add('Local storage',!!(await db.get('prefs','diagnostic')),'IndexedDB can store and read data.');}catch{add('Local storage',false,'Storage is blocked or full.');}try{const r=await fetch('./vendor/emulatorjs/loader.js',{cache:'no-store',signal:AbortSignal.timeout(12000)});const t=await r.text();if(!r.ok||!t.includes('EJS_player'))throw new Error();const c=await fetch('./vendor/emulatorjs/cores/fceumm-legacy-wasm.data',{method:'HEAD',signal:AbortSignal.timeout(12000)});if(!c.ok)throw new Error();add('Emulator files',true,'Loader and NES core are reachable on this host.');}catch{add('Emulator files',false,'Files are missing, blocked, or unreachable.');}add('Audio',!!(window.AudioContext||window.webkitAudioContext),'Sound starts after interacting with the player.');diagResults=results;if(route==='settings')$('#diagnostics').innerHTML=diagnosticMarkup(results);else showModal('Device check',diagnosticMarkup(results));return results;}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function exportLibrary(){download('retropal-library.json',JSON.stringify({format:'retropal-library',version:1,exported:new Date().toISOString(),games:games.map(({hasFile,...g})=>g)},null,2),'application/json');toast('Metadata exported. Export saves separately from the player.');}
async function restoreLibrary(file){if(file.size>20*1024**2)throw new Error('Metadata file exceeds 20 MB.');const data=JSON.parse(await file.text());if(data.format!=='retropal-library'||data.version!==1||!Array.isArray(data.games)||data.games.length>5000)throw new Error('Choose a valid RetroPal library export.');const records=data.games.map(raw=>{if(!raw||typeof raw.id!=='string'||!/^[a-zA-Z0-9-]{1,64}$/.test(raw.id)||!byId(raw.system)||typeof raw.title!=='string'||typeof raw.filename!=='string'||!Number.isFinite(raw.size)||raw.size<0)throw new Error('The export contains an invalid game.');return {id:raw.id,title:raw.title.slice(0,150),filename:raw.filename.slice(0,255),system:raw.system,size:raw.size,added:Number.isFinite(raw.added)?raw.added:Date.now(),lastPlayed:Number.isFinite(raw.lastPlayed)?raw.lastPlayed:0,lastModified:Number.isFinite(raw.lastModified)?raw.lastModified:0,favorite:!!raw.favorite,notes:String(raw.notes||'').slice(0,3000),playSeconds:Math.max(0,Number(raw.playSeconds)||0),fingerprint:typeof raw.fingerprint==='string'?raw.fingerprint.slice(0,600):'',cover:typeof raw.cover==='string'&&/^data:image\/(png|jpeg|webp);base64,[a-zA-Z0-9+/=]+$/.test(raw.cover)&&raw.cover.length<1500000?raw.cover:undefined,hasFile:false};});for(const rec of records){const existing=gameById(rec.id);if(existing){if(existing.filename!==rec.filename||existing.size!==rec.size||existing.system!==rec.system)throw new Error('A game ID conflicts with a local game. Nothing was restored.');rec.hasFile=existing.hasFile;}}if(!records.length)return toast('The export has no games.');await db.write(records.map(value=>({store:'games',key:value.id,value})));games=await db.all('games');render();toast(`${records.length} entries restored. Reimport missing game files.`);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action],#first-import');if(!b)return;const a=b.dataset.action||'import',id=b.dataset.id;try{switch(a){case 'close':if(!importBusy)$('#modal').close();break;case 'import':startImport();break;case 'import-system':startImport(id);break;case 'choose-files':$('#rom-input').click();break;case 'unstage':pending.splice(Number(b.dataset.index),1);renderPending();break;case 'commit-import':await commitImport();break;case 'system':systemDetail(id);break;case 'family':family=b.dataset.family;render();break;case 'filter-system':focusedGameId='';folderId='';libraryScope='all';systemFilter=id;family='all';query='';$('#modal').close();location.hash='library';render();break;case 'clear-filters':focusedGameId='';folderId='';libraryScope='all';query='';family='all';systemFilter='';location.hash='library';render();break;case 'view':view=view==='grid'?'list':'grid';render();break;case 'favorite':await favorite(id);break;case 'detail':await detail(id);break;case 'save-detail':await saveDetail();break;case 'remove-game':removeGame(id);break;case 'confirm-remove':await db.write([{store:'games',key:id,delete:true},{store:'files',key:id,delete:true},{store:'saves',key:id,delete:true},{store:'prefs',key:'auto-state:'+id,delete:true}]);games=games.filter(g=>g.id!==id);$('#modal').close();render();toast('Game removed.');break;case 'cover':$('#cover-input').click();break;case 'remove-cover':{const g=gameById(detailId);delete g.cover;await db.put('games',g.id,g);detail(g.id);render();break;}case 'play':await play(id);break;case 'demo':await demo();break;case 'close-player':await closePlayer();break;case 'save-auto':try{await saveManualState();}catch(err){toast(err.message||'Snapshot could not be saved.');}break;case 'fullscreen':await fullScreen.toggle();break;case 'reset-appearance':Object.assign(prefs,APPEARANCE_DEFAULTS);await savePrefs();render();$('[data-action="reset-appearance"]')?.focus();toast('Appearance reset.');break;case 'bios':biosTarget=id;$('#bios-input').click();break;case 'remove-bios':await db.remove('bios',id);await refreshStorage();toast('BIOS removed.');break;case 'diagnostics':b.disabled=true;b.textContent='Checking…';await diagnostics();b.disabled=false;b.textContent='Run check';break;case 'persist':toast(await navigator.storage?.persist?.()?'Chrome granted persistent storage.':'Chrome did not grant persistent storage. Keep exported backups.');break;case 'export':exportLibrary();break;case 'restore':{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=()=>{if(input.files[0])restoreLibrary(input.files[0]).catch(err=>message('Could not restore',err.message));};input.click();break;}}}catch(err){$('#player').open?toast(err.message||'Please try again.'):message('Something needs attention',err.message||'Try again after checking local storage.');}});
document.addEventListener('input',e=>{if(e.target.id==='search'){focusedGameId='';query=e.target.value;renderGames();}if(e.target.id==='volume'){prefs.volume=Number(e.target.value);e.target.nextElementSibling.value=Math.round(prefs.volume*100)+'%';}});
document.addEventListener('change',async e=>{try{if(e.target.dataset.appearance){const key=e.target.dataset.appearance;if(!['palette','font','shape'].includes(key))return;Object.assign(prefs,normalizeAppearance({...prefs,[key]:e.target.value}));await savePrefs();if($('#appearance-status'))$('#appearance-status').textContent='New look saved on this device.';}if(e.target.id==='system-filter'){systemFilter=e.target.value;renderGames();}if(e.target.id==='sort'){sort=e.target.value;renderGames();}if(e.target.dataset.importIndex!==undefined){pending[Number(e.target.dataset.importIndex)].system=e.target.value;renderPending();}if(e.target.id==='import-system'&&e.target.value){pending.forEach(p=>p.system=e.target.value);renderPending();}if(e.target.dataset.pref){prefs[e.target.dataset.pref]=e.target.checked;await savePrefs();}if(e.target.id==='volume')await savePrefs();}catch{toast('Could not save this preference.');}});
$('#rom-input').accept=accepted.map(x=>'.'+x).join(',');$('#rom-input').onchange=e=>{stageFiles([...e.target.files]);e.target.value='';};
$('#bios-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>32*1024**2)return toast('Use a BIOS file or ZIP under 32 MB.');try{await db.put('bios',biosTarget,{name:file.name,file});await refreshStorage();toast('BIOS stored locally.');}catch{toast('Could not store this BIOS.');}};
$('#cover-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024**2)return toast('Choose a PNG, JPEG, or WebP under 10 MB.');try{const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,600/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const g=gameById(detailId);g.cover=canvas.toDataURL('image/jpeg',.85);await db.put('games',g.id,g);render();detail(g.id);toast('Cover updated.');}catch{toast('Could not read or store this image.');}};
let dragDepth=0;document.addEventListener('dragenter',e=>{if(!e.dataTransfer.types.includes('Files')||$('#player').open)return;e.preventDefault();dragDepth++;document.body.classList.add('dragging');});document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault();});document.addEventListener('dragleave',()=>{if(--dragDepth<=0)document.body.classList.remove('dragging');});document.addEventListener('drop',e=>{e.preventDefault();dragDepth=0;document.body.classList.remove('dragging');if($('#player').open||importBusy)return;if(!$('#import-list'))startImport();stageFiles([...e.dataTransfer.files]);});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open&&!$('#player').open){e.preventDefault();$('#search')?.focus();}});window.addEventListener('hashchange',()=>{if(location.hash==='#main'){$('#main').focus();return;}query='';family='all';render();if(!(route==='library'&&focusedGameId))window.scrollTo({top:0,behavior:'instant'});});
function controllerUpdate(){}
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
$('#mode-label').textContent='Device edition';try{games=await db.all('games');prefs={...prefs,...(await db.get('prefs','settings')||{})};storageReady=true;await initializeDashboard();}catch(err){toast(err.message);}applyPrefs();render();setTimeout(()=>$('#splash')?.remove(),1500);
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'search_retropal_library',description:'Filter the visible local RetroPal library by title or filename.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(typeof input?.query!=='string'||input.query.length>200)throw new Error('query must be a string up to 200 characters');query=input.query;family='all';systemFilter='';history.replaceState(null,'','#library');render();return filteredGames().map(g=>({id:g.id,title:g.title,system:g.system,available:!!g.hasFile}));}});}catch{}}

function continuePanel(){const available=games.filter(g=>g.hasFile&&byId(g.system).core).sort((a,b)=>(b.lastPlayed||0)-(a.lastPlayed||0));const game=available[0];return '<section class="continue-panel"><div><div class="eyebrow">'+(game?.lastPlayed?'PICK UP THE GOOD TIMES':'YOUR NEXT SESSION')+'</div><h2>'+esc(game?game.title:'Your collection, all together.')+'</h2><p>'+ (game?esc(byId(game.system).name)+' · '+(game.lastPlayed?'Last played '+new Date(game.lastPlayed).toLocaleDateString():'Ready when you are'):'Add a browser-supported game to start playing.')+'</p></div>'+(game?action('play','Play game','play','data-id="'+game.id+'"','btn primary'):action('import','Add games','plus','','btn primary'))+'</section>';}
